script:
frappe.ui.form.on('Sample Request AMB', {
    refresh(frm) {
        if (frm.is_new()) return;
        const gen = (print_format, fname, extra) => {
            frappe.call({
                method: 'amb_print.amb_print.api.print_label_pdf',
                args: Object.assign({ doctype: frm.doc.doctype, docname: frm.docname, print_format: print_format, save_attachment: 1 }, extra || {}),
                freeze: true, freeze_message: __('Generating {0}...', [print_format]),
                callback: function(r) {
                    if (!r.message || !r.message.pdf_base64) return;
                    const bin = atob(r.message.pdf_base64);
                    const bytes = new Uint8Array(bin.length);
                    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                    const url = URL.createObjectURL(new Blob([bytes], {type: 'application/pdf'}));
                    const a = document.createElement('a');
                    a.href = url; a.download = fname + '-' + frm.docname + '.pdf';
                    document.body.appendChild(a); a.click(); document.body.removeChild(a);
                    URL.revokeObjectURL(url);
                    if (r.message.file_url) { frappe.show_alert({message: __('{0} attached', [print_format]), indicator: 'green'}); frm.reload_doc(); }
                }
            });
        };
        const layouts = {
            '6x4 2-up (per barrel)': 'Shipping Label AMB',
            'External Box (1 shipment label)': 'Shipping Label Box',
            'Internal 4-up (2x2, cut lines)': 'Shipping Label 4up',
            'Internal 8-up (2x4, cut lines)': 'Shipping Label 8up'
        };
        frm.add_custom_button(__('Shipping Label'), () => {
            const d = new frappe.ui.Dialog({
                title: __('Shipping Label'),
                fields: [
                    {fieldname:'layout', fieldtype:'Select', label:__('Layout'), reqd:1, options: Object.keys(layouts).join('\n'), default:'6x4 2-up (per barrel)'},
                    {fieldname:'start_position', fieldtype:'Select', label:__('Start position (4-up / 8-up)'), options:['A1','B1','A2','B2','A3','B3','A4','B4'].join('\n'), default:'A1', description:__('First free cell on a partially-used sheet.')},
                    {fieldname:'label_qty', fieldtype:'Int', label:__('Labels to print (blank = all)')}
                ],
                primary_action_label: __('Generate'),
                primary_action(v){ d.hide(); gen(layouts[v.layout], 'Shipping-Label', {start_position: v.start_position, label_qty: v.label_qty || null}); }
            });
            d.show();
        }, __('Labels'));
    }
});
